ctive producer ownership");controller.Execute("configurationCancel",new System.Collections.Generic.Dictionary<string,object>{{"id",b.Id}});bool canceled=false;try{second.GetAwaiter().GetResult();}catch(OperationCanceledException){canceled=true;}Check(canceled&&!first.IsCompleted&&controller.Busy,"cancel waiting B preserves active A and aggregate busy");}finally{release.Set();first.GetAwaiter().GetResult();}Check(!controller.Busy&&queue.CanRestart,"both producer and host request counts release after cancellation and completion");}}
