 static void Concurrency(string root,string game,string user,string data){var profiles=new LaunchConfigurationProfiles(data,game,user);var a=profiles.Create("paused A","steam",new[]{"A"});var b=profiles.Create("next B","steam",new[]{"B"});profiles.Select(a.Id);var entered=new System.Threading.ManualResetEventSlim();var release=new System.Threading.ManualResetEventSlim();string source=Path.Combine(root,"downloaded-models");Put(Path.Combine(source,"mods/PZVoxelStudioViewpoint/42/mod.info"),"id=PZVoxelStudioViewpoint\nname=Fixture Models\n");Exception failure=null;var queue=new ModernDispatchQueue();using(var controller=new ModernController(game,user,data,true,(e,ids,report,token,update)=>{entered.Set();release.Wait(token);return ids.ToDictionary(id=>id,id=>source);})){var thread=new System.Threading.Thread(()=>{try{queue.ExecuteConcurrentMutation(controller.CaptureRequest("componentsAction",new System.Collections.Generic.Dictionary<string,object>{{"component","models"},{"operation","install"},{"confirmed",true}})).GetAwaiter().GetResult();}catch(Exception ex){failure=ex;}});thread.Start();Check(entered.Wait(5000),"A download starts");try{controller.Execute("launchConfigurationSelect",new System.Collections.Generic.Dictionary<string,object>{{"id",b.Id}});var memory=queue.ExecuteSnapshot(controller.CaptureRequest("memoryGet",null)).GetAwaiter().GetResult();Check(memory!=null,"host B read remains usable while A download paused");}finally{release.Set();thread.Join(10000);}if(failure!=null)throw failure;Check(new LauncherComponents(profiles.Resolve(a.Id).Context,new Version(42,21)).List(System.Threading.CancellationToken.None).Any(r=>r.Id=="PZVoxelStudioViewpoint"&&r.Enabled),"A callback writes only pinned A");Check(new LauncherComponents(profiles.Resolve(b.Id).Context,new Version(42,21)).List(System.Threading.CancellationToken.None).Length==0,"B component selection untouched");Check(new LaunchConfigurationProfiles(data,game,user).SelectedId==b.Id,"A completion keeps B selected");}}

