 static void HostConcurrency(){var queue=new ModernDispatchQueue();var method=typeof(ModernDispatchQueue).GetMethod("ExecuteConcurrentMutation");Check(method!=null,"host supports counted independent configuration mutations");var entered=new System.Threading.ManualResetEventSlim();var release=new System.Threading.ManualResetEventSlim();var a=(System.Threading.Tasks.Task<object>)method.Invoke(queue,new object[]{new Func<object>(()=>{entered.Set();release.Wait();return null;})});try{Check(entered.Wait(5000),"host A mutation entered");var b=(System.Threading.Tasks.Task<object>)method.Invoke(queue,new object[]{new Func<object>(()=>"B completed")});Check(b.Wait(2000)&&!queue.CanRestart,"host B does not wait for A and restart still counts A");}finally{release.Set();a.Wait();}Check(queue.CanRestart,"host concurrent mutation accounting releases on completion");}

