 static void ComponentAdapter(string root,string game,string user,string data){game=Path.Combine(root,"adapter-steam/steamapps/common/ProjectZomboid");Put(Path.Combine(game,"ProjectZomboid64.exe"),"owned fixture");Put(Path.Combine(game,"ProjectZomboid64.json"),"{\"vmArgs\":[]}");Put(Path.Combine(game,"game-version.txt"),"42.21.0");var profiles=new LaunchConfigurationProfiles(data,game,user);var config=profiles.Create("adapter","steam",new string[0]);profiles.Select(config.Id);var store=new LauncherComponents(profiles.Resolve(config.Id).Context,new Version(42,21));string source=JavaSource(Path.Combine(root,"approval-source"),"FixtureJava");store.Select(source,"FixtureJava",true,System.Threading.CancellationToken.None);var expected=store.List(System.Threading.CancellationToken.None).Single();var json=new System.Web.Script.Serialization.JavaScriptSerializer();Func<object,System.Collections.Generic.Dictionary<string,object>> map=value=>json.Deserialize<System.Collections.Generic.Dictionary<string,object>>(json.Serialize(value));using(var controller=new ModernController(game,user,data,true,null,(e,action,payload,progress,token,batch)=>{JavaSource(Path.Combine(e.Workshop,"123456"),"DownloadedA");JavaSource(Path.Combine(e.Workshop,"123456"),"DownloadedB");return new{id="123456"};})){
  var approval=map(controller.Execute("javaList",null));var row=(System.Collections.Generic.Dictionary<string,object>)((System.Collections.ArrayList)approval["jars"])[0];Check((string)row["sha256"]==expected.Sha256&&(string)row["approvalToken"]==expected.ApprovalStamp&&expected.Sha256!=expected.ApprovalStamp,"approval adapter displays actual content SHA separately from source-bound token");controller.Execute("javaSave",new System.Collections.Generic.Dictionary<string,object>{{"stamp",approval["stamp"]},{"hash",row["approvalToken"]},{"decision",true}});Check(store.List(System.Threading.CancellationToken.None).Single().Decision==true,"native approval accepts exact source-bound decision");
  var install=map(controller.Execute("javaComponentsInstall",new System.Collections.Generic.Dictionary<string,object>{{"id","123456"},{"confirmed",true}}));Check((string)install["status"]=="selectionRequired"&&((System.Collections.ArrayList)install["rows"]).Count==2,"multiple downloaded Java children return concrete selectable rows");var downloaded=map(controller.Execute("javaComponentsInspectDownloaded",new System.Collections.Generic.Dictionary<string,object>{{"id","123456"}}));Check(((System.Collections.ArrayList)downloaded["rows"]).Count==2,"downloaded inspection excludes unrelated selected sources");Directory.Delete(source,true);var incomplete=map(controller.Execute("javaComponentsList",null));Check((bool)incomplete["incomplete"]&&((System.Collections.ArrayList)incomplete["warnings"]).Count>0,"missing selected source is reported as incomplete with named warning");
 }}

 static void AutoBoundDispatch(string game,string user,string data,SaveEnvironmentRecord snapshot){var profiles=new LaunchConfigurationProfiles(data,game,user);profiles.Select("launcher");var json=new System.Web.Script.Serialization.JavaScriptSerializer();Func<object,System.Collections.Generic.Dictionary<string,object>> map=value=>json.Deserialize<System.Collections.Generic.Dictionary<string,object>>(json.Serialize(value));using(var controller=new ModernController(game,user,data,true)){int events=0;controller.StartupPresentation=value=>events++;var begin=map(controller.Execute("startupBegin",new System.Collections.Generic.Dictionary<string,object>{{"targetKind","save"},{"targetId","Sandbox/Capture"}}));controller.Execute("launchPreflight",new System.Collections.Generic.Dictionary<string,object>{{"targetKind","save"},{"startupId",begin["startupId"]}});var child=(ModernController)typeof(ModernController).GetMethod("ConfigurationController",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(controller,null);var attempt=typeof(ModernController).GetField("startupAttempt",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(child);var resolved=(Engine)attempt.GetType().GetField("ResolvedEngine",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(attempt);Check(resolved.FrozenEnvironment!=null&&resolved.FrozenEnvironment.Id==snapshot.Id,"production default dispatcher honors automatic bound-save snapshot");Check(events>0,"bound configuration forwards startup presentation to native host");controller.Execute("startupCancel",new System.Collections.Generic.Dictionary<string,object>{{"startupId",begin["startupId"]}});string file=Path.Combine(user,"Saves/Sandbox/Capture/mods.txt");byte[] original=File.ReadAllBytes(file);try{Put(file,"mods\n{\n mod = Changed,\n}\nmaps\n{\n}\n");begin=map(controller.Execute("startupBegin",new System.Collections.Generic.Dictionary<string,object>{{"targetKind","save"},{"targetId","Sandbox/Capture"}}));bool refused=false;try{controller.Execute("launchPreflight",new System.Collections.Generic.Dictionary<string,object>{{"targetKind","save"},{"startupId",begin["startupId"]}});}catch(IOException){refused=true;}Check(refused,"automatic binding retains strict captured-source save contract");}finally{File.WriteAllBytes(file,original);}}
 }

